<?php
declare(strict_types=1);
namespace Hostider\Support\UI;
use Hostider\Core\{Id,Idempotency,Validation};
use Hostider\Core\Http\HttpError;
use Hostider\Support\{Access,Service,State};
use Hostider\Support\Advanced\Common;
final readonly class Commands
{
    public function __construct(private Context $x){}
    private function fields(string $ctx,string $action,array $p): array
    {
        if($ctx==='client'&&$action!=='send'){throw new HttpError(403,'SUPPORT_ACTION_FORBIDDEN');}$keys=match($action){'send'=>['ticket_id','kind','body','version','draft_version'],'state'=>['ticket_id','version','status'],'move'=>['ticket_id','version','department_id'],default=>throw new HttpError(422,'SUPPORT_UI_ACTION_INVALID')};Validation::fields($p,$keys,$keys);Access::id($p['ticket_id']);Service::version($p['version']);if($action==='send'){Service::version($p['draft_version']);Common::text($p['body'],16000);}if($action==='move'){Access::id($p['department_id']);}if($action==='state'&&!in_array($p['status'],['NEW','WAITING_STAFF','WAITING_CUSTOMER','ON_HOLD','RESOLVED','CLOSED'],true)){throw new HttpError(422,'INVALID_SUPPORT_STATE');}return $p;
    }
    private function authorize(array $u,array $s,string $ctx,string $action,array $p): array
    {
        $m=$this->x->m;if($action==='send'){return (new StateStore($this->x))->ticket($u,$s,$ctx,$p);}if($action==='move'){$source=$m->c->db->execute('SELECT department_id FROM support_tickets WHERE id=?',[$p['ticket_id']])->fetchColumn();$deps=[$p['department_id']];if($source){$deps[]=$source;}sort($deps,SORT_STRING);foreach(array_unique($deps) as $dep){$m->access->department($dep);}}$t=$m->access->ticket($u,$s,$p['ticket_id'],'support.ticket.manage');if($action==='move'){$m->access->require($u,$s,$t['customer_id'],$p['department_id'],'support.ticket.manage');}return $t;
    }
    private function state(array $u,array $s,string $action,array $p,array $t): array
    {
        if((int)$t['version']!==$p['version']){throw new HttpError(409,'SUPPORT_VERSION_CONFLICT');}$m=$this->x->m;$state=['id'=>$t['id'],'version'=>(int)$t['version'],'status'=>$t['status'],'department_id'=>$t['department_id']];if($action==='send'){$r=(new StateStore($this->x))->draft($u,$s,$t,$p['kind'],true);if(!$r||(int)$r['version']!==$p['draft_version']||(int)$r['base_version']!==$p['version']||!hash_equals($m->crypto->decrypt($r['body_encrypted'],'support-ui-draft:'.$r['id']),$p['body'])){throw new HttpError(409,'SUPPORT_DRAFT_SEND_CONFLICT');}$state['draft_id']=$r['id'];$state['draft_version']=(int)$r['version'];$state['body_hmac']=$m->hash(['body'=>$p['body']]);}elseif($action==='state'){State::transition($t['status'],$p['status'],$m->access->department($t['department_id']));}else{$d=$m->access->department($p['department_id']);if(!$d['enabled']||$d['id']===$t['department_id']){throw new HttpError(409,'SUPPORT_MOVE_CONFLICT');}$state['target_department_version']=(int)$d['version'];}return $state;
    }
    public function command(string $ref,string $ctx,string $route,array $body,string $key,string $trace): array
    {
        $this->x->m->gate();Validation::fields($body,['action','payload','confirmation'],['action','payload']);if(!is_string($body['action'])||!in_array($route,['prepare','execute'],true)){throw new HttpError(422,'SUPPORT_UI_ACTION_INVALID');}$action=$body['action'];$p=$this->fields($ctx,$action,Common::object($body['payload']));$work=function(bool $replay)use($ref,$ctx,$route,$body,$action,$p,$trace){return $this->x->run($ref,$ctx,function($u,$s)use($ref,$ctx,$route,$body,$action,$p,$trace,$replay){$m=$this->x->m;$db=$m->c->db;$t=$this->authorize($u,$s,$ctx,$action,$p);if($replay){return [];}$state=$this->state($u,$s,$action,$p,$t);if($route==='prepare'){$id=Id::uuid();$db->execute('INSERT INTO support_ui_confirmations(id,user_id,session_id,identity_version,action,payload_hmac,state_hmac,expires_at) VALUES (?,?,?,?,?,?,?,TIMESTAMPADD(SECOND,300,UTC_TIMESTAMP(6)))',[$id,$u['id'],$s['id'],$u['identity_version'],$action,$m->hash($p),$m->hash($state)]);$m->c->identity->confirmationEvent($u['id'],$id,false);return ['id'=>$id,'action'=>$action,'ticket_version'=>(int)$t['version'],'kind'=>$p['kind']??null,'target'=>$p['status']??$p['department_id']??null,'draft_version'=>$p['draft_version']??null,'body_hmac'=>$state['body_hmac']??null,'expires_in'=>300,'effect'=>'TEST_ONLY_SUPPORT_NO_REAL_DELIVERY'];}
            $a=Common::object($body['confirmation']??[]);Validation::fields($a,['id','accepted'],['id','accepted']);Access::id($a['id']);if($a['accepted']!==true){throw new HttpError(403,'CONFIRMATION_REQUIRED');}$r=$db->execute('SELECT *,UNIX_TIMESTAMP(expires_at) expiry FROM support_ui_confirmations WHERE id=? FOR UPDATE',[$a['id']])->fetch();if(!$r||$r['used_at']!==null||$r['user_id']!==$u['id']||$r['session_id']!==$s['id']||(int)$r['identity_version']!==(int)$u['identity_version']||$r['action']!==$action||(int)$r['expiry']<=time()||!hash_equals($r['payload_hmac'],$m->hash($p))||!hash_equals($r['state_hmac'],$m->hash($state))){throw new HttpError(409,'SUPPORT_UI_CONFIRMATION_INVALID');}$db->execute('UPDATE support_ui_confirmations SET used_at=UTC_TIMESTAMP(6) WHERE id=?',[$r['id']]);$native=['id'=>$t['id'],'version'=>$p['version']];if($action==='send'){$native['body']=$p['body'];$result=(new Service($m->c))->compose($ref,$ctx,$p['kind'],$native,$trace);$db->execute('DELETE FROM support_ui_drafts WHERE id=? AND version=?',[$state['draft_id'],$p['draft_version']]);$result['draft_cleared']=true;}else{$native[$action==='state'?'status':'department_id']=$p[$action==='state'?'status':'department_id'];$result=(new Service($m->c))->compose($ref,$ctx,$action,$native,$trace);}$m->c->identity->confirmationEvent($u['id'],$r['id'],true);return $result;},$ctx==='admin');};return (new Idempotency($this->x->m->c->db))->run($ref,'support-ui:'.$ctx.':'.$route,$key,['hmac'=>$this->x->m->hash($body)],fn()=>$work(false),fn()=>$work(true));
    }
}
